86	struct v_buffer
87	{
88	  uint8_t *start;
89	  uint32_t length;
90	};
91	
92	struct mjpeg_iodev_s
93	{
94	  const uint8_t *data;
95	  size_t         len;
96	  size_t         pos;
97	};
