99	/****************************************************************************
100	 * tjpgd callbacks (copied from uvc_test)
101	 ****************************************************************************/
102	
103	static size_t mjpeg_input(JDEC *jd, uint8_t *buff, size_t nbyte)
104	{
105	  struct mjpeg_iodev_s *io = (struct mjpeg_iodev_s *)jd->device;
106	  size_t avail = io->len - io->pos;
107	  if (nbyte > avail) nbyte = avail;
108	  if (buff) memcpy(buff, io->data + io->pos, nbyte);
109	  io->pos += nbyte;
110	  return nbyte;
111	}
112	
113	/* Output callback: decode to RGB565 display buffer */
114	
115	static uint16_t g_rgbbuf[DISP_WIDTH * DISP_HEIGHT];
116	
117	static int mjpeg_output(JDEC *jd, void *bitmap, JRECT *rect)
118	{
119	  uint8_t *src = (uint8_t *)bitmap;
120	  uint32_t x;
121	  uint32_t y;
122	  uint32_t cpw = jd->width < DISP_WIDTH ? jd->width : DISP_WIDTH;
123	
124	  for (y = rect->top; y <= rect->bottom && y < DISP_HEIGHT; y++)
125	    {
126	      for (x = rect->left; x <= rect->right && x < DISP_WIDTH; x++)
127	        {
128	          uint8_t b = *src++;
129	          uint8_t g = *src++;
130	          uint8_t r = *src++;
131	          g_rgbbuf[y * cpw + x] =
132	            ((r & 0xf8) << 8) | ((g & 0xfc) << 3) | (b >> 3);
133	        }
134	
135	      if (rect->right >= DISP_WIDTH)
136	        src += (rect->right - DISP_WIDTH + 1) * 3;
137	    }
138	
139	  return 1;
140	}
141	
142	/* Output callback: decode to SSD input buffer (300x300 RGB INT8) */
143	
144	static int8_t g_ssd_input[SSD_INPUT_SIZE];
145	
146	static int mjpeg_output_ssd(JDEC *jd, void *bitmap, JRECT *rect)
147	{
148	  uint8_t *src = (uint8_t *)bitmap;
149	  uint32_t x;
150	  uint32_t y;
151	  uint32_t src_w = jd->width;
152	  uint32_t src_h = jd->height;
153	
154	  for (y = rect->top; y <= rect->bottom; y++)
155	    {
156	      for (x = rect->left; x <= rect->right; x++)
157	        {
158	          uint8_t b = *src++;
159	          uint8_t g = *src++;
160	          uint8_t r = *src++;
161	
162	          /* Map to 300x300 grid */
163	
164	          int dx = (int)(x * SSD_INPUT_W / src_w);
165	          int dy = (int)(y * SSD_INPUT_H / src_h);
166	          if (dx >= SSD_INPUT_W) dx = SSD_INPUT_W - 1;
167	          if (dy >= SSD_INPUT_H) dy = SSD_INPUT_H - 1;
168	
169	          int idx = (dy * SSD_INPUT_W + dx) * SSD_INPUT_C;
170	          g_ssd_input[idx + 0] = static_cast<int8_t>(r - 128);
171	          g_ssd_input[idx + 1] = static_cast<int8_t>(g - 128);
172	          g_ssd_input[idx + 2] = static_cast<int8_t>(b - 128);
173	        }
174	    }
175	
176	  return 1;
177	}
