224	/****************************************************************************
225	 * Drawing Helpers
226	 ****************************************************************************/
227	
228	static void draw_pixel(int x, int y, uint16_t color)
229	{
230	  if (x >= 0 && x < DISP_WIDTH && y >= 0 && y < DISP_HEIGHT)
231	    g_rgbbuf[y * DISP_WIDTH + x] = color;
232	}
233	
234	static void draw_hline(int x0, int x1, int y, uint16_t color)
235	{
236	  for (int x = x0; x <= x1; x++)
237	    draw_pixel(x, y, color);
238	}
239	
240	static void draw_vline(int x, int y0, int y1, uint16_t color)
241	{
242	  for (int y = y0; y <= y1; y++)
243	    draw_pixel(x, y, color);
244	}
245	
246	/* Draw a rectangle outline (2px thick for visibility) */
247	
248	static void draw_rect(int x0, int y0, int x1, int y1, uint16_t color)
249	{
250	  draw_hline(x0, x1, y0, color);
251	  draw_hline(x0, x1, y0 + 1, color);
252	  draw_hline(x0, x1, y1, color);
253	  draw_hline(x0, x1, y1 - 1, color);
254	  draw_vline(x0, y0, y1, color);
255	  draw_vline(x0 + 1, y0, y1, color);
256	  draw_vline(x1, y0, y1, color);
257	  draw_vline(x1 - 1, y0, y1, color);
258	}
259	
260	static void draw_filled_rect(int x0, int y0, int x1, int y1,
261	                              uint16_t color)
262	{
263	  for (int y = y0; y <= y1; y++)
264	    for (int x = x0; x <= x1; x++)
265	      draw_pixel(x, y, color);
266	}
267	
268	static void draw_char(int x, int y, char c, uint16_t color, int scale)
269	{
270	  if (c < 32 || c > 90) return;
271	  int idx = c - 32;
272	  if (idx < 0 || idx >= (int)(sizeof(g_font5x7) / FONT_W)) return;
273	  const uint8_t *glyph = g_font5x7[idx];
274	  for (int col = 0; col < FONT_W; col++)
275	    {
276	      uint8_t line = glyph[col];
277	      for (int row = 0; row < FONT_H; row++)
278	        if (line & (1 << row))
279	          for (int sy = 0; sy < scale; sy++)
280	            for (int sx = 0; sx < scale; sx++)
281	              draw_pixel(x + col * scale + sx, y + row * scale + sy, color);
282	    }
283	}
284	
285	static void draw_string(int x, int y, const char *str,
286	                         uint16_t color, int scale)
287	{
288	  while (*str)
289	    {
290	      draw_char(x, y, *str, color, scale);
291	      x += (FONT_W + 1) * scale;
292	      str++;
293	    }
294	}
