300	static int fb_open(void)
301	{
302	  g_fbfd = open(FB_DEV_PATH, O_RDWR);
303	  if (g_fbfd < 0)
304	    {
305	      printf("ERROR: open %s failed: %d\n", FB_DEV_PATH, errno);
306	      return -errno;
307	    }
308	
309	  int ret = ioctl(g_fbfd, LCDDEVIO_GETVIDEOINFO, (uintptr_t)&g_vinfo);
310	  if (ret < 0)
311	    {
312	      printf("ERROR: LCDDEVIO_GETVIDEOINFO failed: %d\n", errno);
313	      close(g_fbfd);
314	      g_fbfd = -1;
315	      return -errno;
316	    }
317	
318	  printf("LCD: %ux%u fmt=%u\n", g_vinfo.xres, g_vinfo.yres, g_vinfo.fmt);
319	  return OK;
320	}
321	
322	static void fb_blit(uint32_t w, uint32_t h)
323	{
324	  struct lcddev_area_s area;
325	  memset(&area, 0, sizeof(area));
326	  area.row_start = 0;
327	  area.row_end   = h - 1;
328	  area.col_start = 0;
329	  area.col_end   = w - 1;
330	  area.stride    = w * 2;
331	  area.data      = (FAR uint8_t *)g_rgbbuf;
332	  ioctl(g_fbfd, LCDDEVIO_PUTAREA, (uintptr_t)&area);
333	}
