347	/****************************************************************************
348	 * main
349	 ****************************************************************************/
350	
351	extern "C" int main(int argc, char *argv[])
352	{
353	  const tflite::Model *model = nullptr;
354	  TfLiteTensor *input = nullptr;
355	  int iterations = 1;
356	  int use_camera = 0;
357	  int opt;
358	
359	  while ((opt = getopt(argc, argv, "cr:h")) != -1)
360	    switch (opt)
361	      {
362	        case 'c': use_camera = 1; break;
363	        case 'r': iterations = atoi(optarg); break;
364	        default: print_usage(argv[0]); return (opt == 'h') ? 0 : 1;
365	      }
366	
367	  tflite::InitializeTarget();
368	  printf("=== Person Detection (SSD) ===\n");
369	  fflush(stdout);
370	
371	  /* Load SSD model */
372	
373	  model = tflite::GetModel(g_ssd_model_data);
374	  if (model->version() != TFLITE_SCHEMA_VERSION)
375	    { printf("ERROR: Model version mismatch\n"); return 1; }
376	
377	  /* Register all operators needed by SSD MobileNet V2 */
378	
379	  static tflite::MicroMutableOpResolver<20> op_resolver;
380	  op_resolver.AddConv2D();
381	  op_resolver.AddDepthwiseConv2D();
382	  op_resolver.AddMaxPool2D();
383	  op_resolver.AddAveragePool2D();
384	  op_resolver.AddReshape();
385	  op_resolver.AddSoftmax();
386	  op_resolver.AddConcatenation();
387	  op_resolver.AddAdd();
388	  op_resolver.AddMul();
389	  op_resolver.AddLogistic();
390	  op_resolver.AddQuantize();
391	  op_resolver.AddDequantize();
392	  op_resolver.AddFullyConnected();
393	  op_resolver.AddCustom("TFLite_Detection_PostProcess",
394	                        tflite::Register_DETECTION_POSTPROCESS());
395	
396	  tflite::MicroInterpreter interpreter(
397	      model, op_resolver, g_tensor_arena, TENSOR_ARENA_SIZE);
398	
399	  if (interpreter.AllocateTensors() != kTfLiteOk)
400	    { printf("ERROR: AllocateTensors failed (arena too small?)\n"); return 1; }
401	
402	  input = interpreter.input(0);
403	
404	  printf("Model loaded, input: %dx%dx%d, arena: %zu/%d bytes\n",
405	         input->dims->data[1], input->dims->data[2], input->dims->data[3],
406	         interpreter.arena_used_bytes(), TENSOR_ARENA_SIZE);
407	  fflush(stdout);
408	
409	  /* =========================================================================
410	   * Camera mode with bounding boxes
411	   * ========================================================================= */
412	
413	  if (use_camera)
414	    {
415	      struct v4l2_format fmt;
416	      struct v4l2_requestbuffers req;
417	      struct v4l2_buffer buf;
418	      struct v_buffer *buffers;
419	      enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
420	      int fd;
421	      int ret;
422	      int i;
423	      int frames = 0;
424	      int run_forever = (iterations == 0);
425	      int fb_ok = (fb_open() == OK);
426	
427	      /* Camera setup (same as uvc_test) */
428	
429	      capture_initialize(VIDEO_DEV_PATH);
430	      fd = open(VIDEO_DEV_PATH, O_RDWR);
431	      if (fd < 0)
432	        { printf("ERROR: open %s: %d\n", VIDEO_DEV_PATH, errno); return 1; }
433	
434	      memset(&fmt, 0, sizeof(fmt));
435	      fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
436	      fmt.fmt.pix.width = DISP_WIDTH;
437	      fmt.fmt.pix.height = DISP_HEIGHT;
438	      fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;
439	      fmt.fmt.pix.field = V4L2_FIELD_NONE;
440	      ioctl(fd, VIDIOC_S_FMT, (uintptr_t)&fmt);
441	      if (fmt.fmt.pix.sizeimage == 0)
442	        fmt.fmt.pix.sizeimage = DISP_WIDTH * DISP_HEIGHT * 2;
443	
444	      memset(&req, 0, sizeof(req));
445	      req.count = BUF_COUNT;
446	      req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
447	      req.memory = V4L2_MEMORY_USERPTR;
448	      ioctl(fd, VIDIOC_REQBUFS, (uintptr_t)&req);
449	
450	      buffers = (struct v_buffer *)malloc(req.count * sizeof(struct v_buffer));
451	      for (i = 0; i < (int)req.count; i++)
452	        {
453	          buffers[i].length = fmt.fmt.pix.sizeimage;
454	          buffers[i].start = (uint8_t *)memalign(64, buffers[i].length);
455	          memset(&buf, 0, sizeof(buf));
456	          buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
457	          buf.memory = V4L2_MEMORY_USERPTR;
458	          buf.index = i;
459	          buf.m.userptr = (uintptr_t)buffers[i].start;
460	          buf.length = buffers[i].length;
461	          ioctl(fd, VIDIOC_QBUF, (uintptr_t)&buf);
462	        }
463	
464	      ioctl(fd, VIDIOC_STREAMON, (uintptr_t)&type);
465	      printf("Camera streaming (SSD %dx%d input)\n", SSD_INPUT_W, SSD_INPUT_H);
466	      fflush(stdout);
467	
468	      /* Main loop */
469	
470	      while (run_forever || frames < iterations)
471	        {
472	          struct timeval t0, t1, t2, t3;
473	          gettimeofday(&t0, NULL);
474	
475	          /* DQBUF + snapshot (same as uvc_test) */
476	
477	          memset(&buf, 0, sizeof(buf));
478	          buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
479	          buf.memory = V4L2_MEMORY_USERPTR;
480	          ret = ioctl(fd, VIDIOC_DQBUF, (uintptr_t)&buf);
481	          if (ret < 0) break;
482	
483	          uint32_t n = buf.bytesused;
484	          if (n > sizeof(g_framecopy)) n = sizeof(g_framecopy);
485	          memcpy(g_framecopy, (const void *)buf.m.userptr, n);
486	          ioctl(fd, VIDIOC_QBUF, (uintptr_t)&buf);
487	
488	          gettimeofday(&t1, NULL);
489	
490	          /* Decode JPEG twice: once for display, once for SSD input */
491	
492	          {
493	            static uint8_t jdwork[4096];
494	            struct mjpeg_iodev_s iodev;
495	
496	            /* Pass 1: decode to RGB565 display buffer */
497	
498	            {
499	              JDEC jdec;
500	              iodev.data = g_framecopy;
501	              iodev.len  = n;
502	              iodev.pos  = 0;
503	              if (jd_prepare(&jdec, mjpeg_input, jdwork,
504	                             sizeof(jdwork), &iodev) == JDR_OK)
505	                jd_decomp(&jdec, mjpeg_output, 0);
506	            }
507	
508	            /* Pass 2: decode to SSD input buffer (300x300 RGB INT8) */
509	
510	            {
511	              JDEC jdec;
512	              iodev.data = g_framecopy;
513	              iodev.len  = n;
514	              iodev.pos  = 0;
515	              memset(g_ssd_input, 0, sizeof(g_ssd_input));
516	              if (jd_prepare(&jdec, mjpeg_input, jdwork,
517	                             sizeof(jdwork), &iodev) == JDR_OK)
518	                jd_decomp(&jdec, mjpeg_output_ssd, 0);
519	            }
520	          }
521	
522	          gettimeofday(&t2, NULL);
523	
524	          /* Run SSD inference */
525	
526	          memcpy(input->data.int8, g_ssd_input, SSD_INPUT_SIZE);
527	
528	          int num_persons = 0;
529	          if (interpreter.Invoke() == kTfLiteOk)
530	            {
531	              /* SSD output tensors:
532	               *   0: boxes   [1, N, 4] float (ymin, xmin, ymax, xmax) [0,1]
533	               *   1: classes [1, N]    float (class ID)
534	               *   2: scores  [1, N]    float (confidence)
535	               *   3: num_detections [1] float
536	               */
537	
538	              TfLiteTensor *out_boxes  = interpreter.output(0);
539	              TfLiteTensor *out_classes = interpreter.output(1);
540	              TfLiteTensor *out_scores = interpreter.output(2);
541	              TfLiteTensor *out_num    = interpreter.output(3);
542	
543	              int num_det = (int)out_num->data.f[0];
544	              if (num_det > SSD_MAX_DETECTIONS)
545	                num_det = SSD_MAX_DETECTIONS;
546	
547	              for (int d = 0; d < num_det; d++)
548	                {
549	                  float score = out_scores->data.f[d];
550	                  int cls = (int)out_classes->data.f[d];
551	
552	                  /* Only draw boxes for "person" class (COCO ID 0)
553	                   * with confidence above threshold */
554	
555	                  if (cls == COCO_PERSON_CLASS && score >= DETECT_THRESHOLD)
556	                    {
557	                      float ymin = out_boxes->data.f[d * 4 + 0];
558	                      float xmin = out_boxes->data.f[d * 4 + 1];
559	                      float ymax = out_boxes->data.f[d * 4 + 2];
560	                      float xmax = out_boxes->data.f[d * 4 + 3];
561	
562	                      /* Map normalized [0,1] to screen coordinates */
563	
564	                      int sx1 = (int)(xmin * DISP_WIDTH);
565	                      int sy1 = (int)(ymin * DISP_HEIGHT);
566	                      int sx2 = (int)(xmax * DISP_WIDTH);
567	                      int sy2 = (int)(ymax * DISP_HEIGHT);
568	
569	                      /* Clamp */
570	
571	                      if (sx1 < 0) sx1 = 0;
572	                      if (sy1 < 0) sy1 = 0;
573	                      if (sx2 >= DISP_WIDTH)  sx2 = DISP_WIDTH - 1;
574	                      if (sy2 >= DISP_HEIGHT) sy2 = DISP_HEIGHT - 1;
575	
576	                      /* Draw green bounding box */
577	
578	                      uint16_t green = ((0 << 11) | (63 << 5) | 0);
579	                      draw_rect(sx1, sy1, sx2, sy2, green);
580	
581	                      /* Draw label with confidence */
582	
583	                      char label[16];
584	                      snprintf(label, sizeof(label), "P:%d%%",
585	                               (int)(score * 100));
586	
587	                      /* Label background */
588	
589	                      int lw = (FONT_W + 1) * FONT_SCALE * strlen(label);
590	                      int lh = FONT_H * FONT_SCALE;
591	                      draw_filled_rect(sx1, sy1 - lh - 2, sx1 + lw, sy1 - 1,
592	                                       green);
593	
594	                      /* Label text */
595	
596	                      draw_string(sx1, sy1 - lh - 1, label,
597	                                  0xFFFF, FONT_SCALE);
598	
599	                      num_persons++;
600	                    }
601	                }
602	            }
603	
604	          gettimeofday(&t3, NULL);
605	
606	          /* Blit to LCD */
607	
608	          if (fb_ok)
609	            fb_blit(DISP_WIDTH, DISP_HEIGHT);
610	
611	          frames++;
612	
613	          /* Timing every 10 frames */
614	
615	          if (frames % 10 == 0)
616	            {
617	              int cap_us   = (t1.tv_sec - t0.tv_sec) * 1000000 +
618	                             (t1.tv_usec - t0.tv_usec);
619	              int decode_us = (t2.tv_sec - t1.tv_sec) * 1000000 +
620	                              (t2.tv_usec - t1.tv_usec);
621	              int infer_us  = (t3.tv_sec - t2.tv_sec) * 1000000 +
622	                              (t3.tv_usec - t2.tv_usec);
623	              int total_us  = (t3.tv_sec - t0.tv_sec) * 1000000 +
624	                              (t3.tv_usec - t0.tv_usec);
625	              printf("\nTiming: cap=%dms decode=%dms infer=%dms total=%dms "
626	                     "(%dfps) persons=%d\n",
627	                     cap_us/1000, decode_us/1000, infer_us/1000,
628	                     total_us/1000, total_us > 0 ? 1000000/total_us : 0,
629	                     num_persons);
630	            }
631	
632	          printf("\rFrame %d: %d person(s) detected   ",
633	                 frames, num_persons);
634	          fflush(stdout);
635	        }
636	
637	      printf("\nDone. %d frames.\n", frames);
638	
639	      /* Cleanup */
640	
641	      ioctl(fd, VIDIOC_STREAMOFF, (uintptr_t)&type);
642	      for (i = 0; i < (int)req.count; i++)
643	        if (buffers[i].start) free(buffers[i].start);
644	      free(buffers);
645	      close(fd);
646	      if (fb_ok) close(g_fbfd);
647	      return 0;
648	    }
649	
650	  /* Single image mode not supported for SSD */
651	
652	  printf("Use -c for camera mode with SSD bounding boxes.\n");
653	  return 0;
654	}
