84	
85	struct mjpeg_iodev_s
86	{
87	  const uint8_t *data;
88	  size_t         len;
89	  size_t         pos;
90	};
91	
92	static size_t mjpeg_input(JDEC *jd, uint8_t *buff, size_t nbyte)
93	{
94	  struct mjpeg_iodev_s *io = (struct mjpeg_iodev_s *)jd->device;
95	  size_t avail = io->len - io->pos;
96	  if (nbyte > avail) nbyte = avail;
97	  if (buff) memcpy(buff, io->data + io->pos, nbyte);
98	  io->pos += nbyte;
99	  return nbyte;
100	}
101	
102	/* Output: write to g_rgbbuf (RGB565 for LCD) and optionally g_graybuf */
103	
104	static int8_t  *g_inf_gray = nullptr;  /* inference grayscale buffer */
105	static uint32_t g_inf_srcw = 0;
106	static uint32_t g_inf_srch = 0;
107	
108	static int mjpeg_output(JDEC *jd, void *bitmap, JRECT *rect)
109	{
110	  uint8_t *src = (uint8_t *)bitmap;
111	  uint32_t x;
112	  uint32_t y;
113	  uint32_t cpw = jd->width < TEST_WIDTH ? jd->width : TEST_WIDTH;
114	
115	  for (y = rect->top; y <= rect->bottom && y < TEST_HEIGHT; y++)
116	    {
117	      for (x = rect->left; x <= rect->right && x < TEST_WIDTH; x++)
118	        {
119	          uint8_t b = *src++;
120	          uint8_t g = *src++;
121	          uint8_t r = *src++;
122	          g_rgbbuf[y * cpw + x] =
123	            ((r & 0xf8) << 8) | ((g & 0xfc) << 3) | (b >> 3);
124	
125	          /* Also convert to grayscale for inference */
126	
127	          if (g_inf_gray && g_inf_srcw > 0 && g_inf_srch > 0)
128	            {
129	              int dx = (int)(x * NUM_COLS / g_inf_srcw);
130	              int dy = (int)(y * NUM_ROWS / g_inf_srch);
131	              if (dx >= NUM_COLS) dx = NUM_COLS - 1;
132	              if (dy >= NUM_ROWS) dy = NUM_ROWS - 1;
133	              int gray = (77 * r + 150 * g + 29 * b) >> 8;
134	              g_inf_gray[dy * NUM_COLS + dx] =
135	                  static_cast<int8_t>(gray - 128);
136	            }
137	        }
138	
139	      if (rect->right >= TEST_WIDTH)
140	        src += (rect->right - TEST_WIDTH + 1) * 3;
141	    }
142	
143	  return 1;
144	}
