209	
210	static void draw_pixel(int x, int y, uint16_t color)
211	{
212	  if (x >= 0 && x < (int)TEST_WIDTH && y >= 0 && y < (int)TEST_HEIGHT)
213	    g_rgbbuf[y * TEST_WIDTH + x] = color;
214	}
215	
216	static void draw_filled_rect(int x0, int y0, int x1, int y1,
217	                              uint16_t color)
218	{
219	  for (int y = y0; y <= y1; y++)
220	    for (int x = x0; x <= x1; x++)
221	      draw_pixel(x, y, color);
222	}
223	
224	static void draw_char(int x, int y, char c, uint16_t color, int scale)
225	{
226	  if (c < 32 || c > 90) return;
227	  int idx = c - 32;
228	  if (idx < 0 || idx >= (int)(sizeof(g_font5x7) / FONT_W)) return;
229	  const uint8_t *glyph = g_font5x7[idx];
230	  for (int col = 0; col < FONT_W; col++)
231	    {
232	      uint8_t line = glyph[col];
233	      for (int row = 0; row < FONT_H; row++)
234	        if (line & (1 << row))
235	          for (int sy = 0; sy < scale; sy++)
236	            for (int sx = 0; sx < scale; sx++)
237	              draw_pixel(x + col * scale + sx, y + row * scale + sy, color);
238	    }
239	}
240	
241	static void draw_string(int x, int y, const char *str,
242	                         uint16_t color, int scale)
243	{
244	  while (*str)
245	    {
246	      draw_char(x, y, *str, color, scale);
247	      x += (FONT_W + 1) * scale;
248	      str++;
249	    }
250	}
