335	{
336	  printf("Usage: %s [options]\n", progname);
337	  printf("  -c         Camera mode\n");
338	  printf("  -t <file>  Load BMP image\n");
339	  printf("  -r <N>     N frames (0=forever)\n");
340	  printf("  -h         Help\n");
