343	/****************************************************************************
344	 * main
345	 ****************************************************************************/
346	
347	extern "C" int main(int argc, char *argv[])
348	{
349	  const tflite::Model *model = nullptr;
350	  TfLiteTensor *input = nullptr;
351	  TfLiteTensor *output = nullptr;
352	  const char *image_path = nullptr;
353	  int iterations = 1;
354	  int use_camera = 0;
355	  int opt;
356	
357	  while ((opt = getopt(argc, argv, "ct:r:h")) != -1)
358	    switch (opt)
359	      {
360	        case 'c': use_camera = 1; break;
361	        case 't': image_path = optarg; break;
362	        case 'r': iterations = atoi(optarg); break;
363	        default: print_usage(argv[0]); return (opt == 'h') ? 0 : 1;
364	      }
365	
366	  tflite::InitializeTarget();
367	  printf("=== Person Detection Demo ===\n");
368	  fflush(stdout);
369	
370	  model = tflite::GetModel(g_person_detect_model_data);
371	  if (model->version() != TFLITE_SCHEMA_VERSION)
372	    { printf("ERROR: Model version mismatch\n"); return 1; }
373	
374	  tflite::MicroMutableOpResolver<5> op_resolver;
375	  op_resolver.AddConv2D(tflite::Register_CONV_2D_INT8());
376	  op_resolver.AddDepthwiseConv2D(tflite::Register_DEPTHWISE_CONV_2D_INT8());
377	  op_resolver.AddAveragePool2D(tflite::Register_AVERAGE_POOL_2D_INT8());
378	  op_resolver.AddReshape();
379	  op_resolver.AddSoftmax(tflite::Register_SOFTMAX_INT8());
380	
381	  tflite::MicroInterpreter interpreter(
382	      model, op_resolver, g_tensor_arena, TENSOR_ARENA_SIZE);
383	
384	  if (interpreter.AllocateTensors() != kTfLiteOk)
385	    { printf("ERROR: AllocateTensors failed\n"); return 1; }
386	
387	  input  = interpreter.input(0);
388	  output = interpreter.output(0);
389	
390	  printf("Model loaded, arena: %zu/%d bytes\n",
391	         interpreter.arena_used_bytes(), TENSOR_ARENA_SIZE);
392	  fflush(stdout);
393	
394	  /* =========================================================================
395	   * Camera mode — logic copied from uvc_test + inference overlay
396	   * ========================================================================= */
397	
398	  if (use_camera)
399	    {
400	      struct v4l2_format fmt;
401	      struct v4l2_requestbuffers req;
402	      struct v4l2_buffer buf;
403	      struct v_buffer *buffers;
