242	          break;
243	        }
244	        default:
245	          MicroPrintf("Weight type %s (%d) not supported.",
246	                      TfLiteTypeGetName(filter->type), filter->type);
247	          return kTfLiteError;
248	      }
249	      break;
250	    }
251	    default:
252	      MicroPrintf("Type %s (%d) not supported.", TfLiteTypeGetName(input->type),
253	                  input->type);
254	      return kTfLiteError;
255	  }
256	  return kTfLiteOk;
257	}
