47	template <unsigned int tOpCount>
48	class MicroMutableOpResolver : public MicroOpResolver {
49	 public:
50	  TF_LITE_REMOVE_VIRTUAL_DELETE
51	
52	  explicit MicroMutableOpResolver() {}
53	
54	  const TFLMRegistration* FindOp(tflite::BuiltinOperator op) const override {
55	    if (op == BuiltinOperator_CUSTOM) return nullptr;
56	
57	    for (unsigned int i = 0; i < registrations_len_; ++i) {
58	      const TFLMRegistration& registration = registrations_[i];
59	      if (registration.builtin_code == op) {
60	        return &registration;
61	      }
62	    }
63	    return nullptr;
64	  }
65	
66	  const TFLMRegistration* FindOp(const char* op) const override {
67	    for (unsigned int i = 0; i < registrations_len_; ++i) {
68	      const TFLMRegistration& registration = registrations_[i];
69	      if ((registration.builtin_code == BuiltinOperator_CUSTOM) &&
70	          (strcmp(registration.custom_name, op) == 0)) {
71	        return &registration;
72	      }
73	    }
74	    return nullptr;
75	  }
76	
77	  TfLiteBridgeBuiltinParseFunction GetOpDataParser(
78	      BuiltinOperator op) const override {
79	    TFLITE_DCHECK(num_buitin_ops_ <= tOpCount);
80	    for (unsigned int i = 0; i < num_buitin_ops_; ++i) {
81	      if (builtin_codes_[i] == op) return builtin_parsers_[i];
82	    }
83	    return nullptr;
84	  }
85	
86	  // Registers a Custom Operator with the MicroOpResolver.
87	  //
88	  // Only the first call for a given name will be successful. i.e. if this
89	  // function is called again for a previously added Custom Operator, the
90	  // MicroOpResolver will be unchanged and this function will return
91	  // kTfLiteError.
92	  TfLiteStatus AddCustom(const char* name,
93	                         const TFLMRegistration* registration) {
94	    if (registrations_len_ >= tOpCount) {
95	      MicroPrintf(
96	          "Couldn't register custom op '%s', resolver size is too"
97	          "small (%d)",
98	          name, tOpCount);
99	      return kTfLiteError;
100	    }
101	
102	    if (FindOp(name) != nullptr) {
103	      MicroPrintf("Calling AddCustom for the same op more than once ");
104	      MicroPrintf("is not supported (Op: %s).", name);
105	      return kTfLiteError;
106	    }
107	
108	    TFLMRegistration* new_registration = &registrations_[registrations_len_];
109	    registrations_len_ += 1;
110	
111	    *new_registration = *registration;
112	    new_registration->builtin_code = BuiltinOperator_CUSTOM;
113	    new_registration->custom_name = name;
114	    return kTfLiteOk;
115	  }
