677	      return kTfLiteError;
678	    }
679	
680	    if (FindOp(op) != nullptr) {
681	      MicroPrintf("Calling AddBuiltin with the same op more than ");
682	      MicroPrintf("once is not supported (Op: #%d).", op);
683	      return kTfLiteError;
684	    }
685	
686	    if (registrations_len_ >= tOpCount) {
687	      MicroPrintf("Couldn't register builtin op #%d, resolver size ", op);
688	      MicroPrintf("is too small (%d).", tOpCount);
689	      return kTfLiteError;
690	    }
691	
692	    registrations_[registrations_len_] = registration;
693	    // Strictly speaking, the builtin_code is not necessary for TFLM but filling
694	    // it in regardless.
695	    registrations_[registrations_len_].builtin_code = op;
696	    registrations_len_++;
697	
698	    builtin_codes_[num_buitin_ops_] = op;
699	    builtin_parsers_[num_buitin_ops_] = parser;
700	    num_buitin_ops_++;
701	
702	    return kTfLiteOk;
703	  }
