503	TfLiteStatus Eval(TfLiteContext* context, TfLiteNode* node) {
504	  const TfLiteEvalTensor* input =
505	      tflite::micro::GetEvalInput(context, node, kConvInputTensor);
506	  const TfLiteEvalTensor* filter =
507	      tflite::micro::GetEvalInput(context, node, kConvWeightsTensor);
508	  const TfLiteEvalTensor* bias =
509	      (NumInputs(node) == 3)
510	          ? tflite::micro::GetEvalInput(context, node, kConvBiasTensor)
511	          : nullptr;
512	  TfLiteEvalTensor* output =
513	      tflite::micro::GetEvalOutput(context, node, kConvOutputTensor);
514	
515	  TFLITE_DCHECK(node->builtin_data != nullptr);
516	  const auto& params =
517	      *(reinterpret_cast<TfLiteConvParams*>(node->builtin_data));
518	  TFLITE_DCHECK(node->user_data != nullptr);
519	  const OpData& data = *(static_cast<const OpData*>(node->user_data));
520	
521	  TF_LITE_ENSURE_EQ(context, input->type, output->type);
522	  TF_LITE_ENSURE_MSG(
523	      context,
524	      input->type == filter->type ||
525	          (input->type == kTfLiteInt16 && filter->type == kTfLiteInt8) ||
526	          (input->type == kTfLiteInt8 && filter->type == kTfLiteInt4),
527	      "Hybrid models are not supported on TFLite Micro.");
528	
529	  switch (input->type) {  // Already know in/out types are same.
530	    case kTfLiteFloat32: {
531	      tflite::reference_ops::Conv(
532	          ConvParamsFloat(params, data.reference_op_data),
533	          tflite::micro::GetTensorShape(input),
534	          tflite::micro::GetTensorData<float>(input),
535	          tflite::micro::GetTensorShape(filter),
536	          tflite::micro::GetTensorData<float>(filter),
537	          tflite::micro::GetTensorShape(bias),
538	          tflite::micro::GetOptionalTensorData<float>(bias),
539	          tflite::micro::GetTensorShape(output),
540	          tflite::micro::GetTensorData<float>(output),
541	          tflite::micro::GetTensorShape(nullptr), nullptr);
542	      break;
543	    }
544	    case kTfLiteInt8: {
545	      switch (filter->type) {
546	        case kTfLiteInt4: {
547	          return EvalQuantizedPerChannel<int8_t, int32_t, kTfLiteInt4>(
548	              context, node, params, data, input, filter, bias, output);
549	        }

